arguments.command:
bash -lc 'python - <<"PY"
import io,sys,re
p = "/src/libxml2/parserInternals.c"
with open(p, "r", encoding="utf-8", errors="ignore") as f:
    s = f.read()
anchor = "int\nxmlCopyCharMultiByte(xmlChar *out, int val) {"
pos = s.find(anchor)
if pos==-1:
    print("ANCHOR_NOT_FOUND", file=sys.stderr)
    sys.exit(1)
# find start of brace after anchor
brace_pos = s.find("{", pos)
if brace_pos==-1:
    print("OPEN_BRACE_NOT_FOUND", file=sys.stderr)
    sys.exit(1)
# find matching closing brace
depth = 0
end = None
for i in range(brace_pos, len(s)):
    ch = s[i]
    if ch == '{':
        depth += 1
    elif ch == '}':
        depth -= 1
        if depth == 0:
            end = i+1
            break
if end is None:
    print("NO_END_BRACE", file=sys.stderr)
    sys.exit(1)
new_fn = '''int
xmlCopyCharMultiByte(xmlChar *out, int val) {
    if ((out == NULL) || (val < 0)) return(0);
    xmlChar *savedout = out;
    int bits;
    if  (val >= 0x80) {
        int needed;
        if (val <   0x800) { *out++= (val >>  6) | 0xC0;  bits=  0; needed = 2; }
        else if (val < 0x10000) { *out++= (val >> 12) | 0xE0;  bits=  6; needed = 3;}
        else if (val < 0x110000)  { *out++= (val >> 18) | 0xF0;  bits= 12; needed = 4; }
        else {
            xmlErrEncodingInt(NULL, XML_ERR_INVALID_CHAR,
                "Internal error, xmlCopyCharMultiByte 0x%X out of bound\n",
                val);
            return(0);
        }
        /* Guard against buffer overruns: ensure we never write more than 4 bytes */
        if ((out - savedout) > 4) return 0;
        for ( ; bits >= 0; bits-= 6) {
            if ((out - savedout) >= 4) return (out - savedout);
            *out++= ((val >> bits) & 0x3F) | 0x80 ;
        }
        return (out - savedout);
    }
    *out = (xmlChar)val;
    return 1;
}
'''
new_s = s[:pos] + new_fn + s[end:]
with open(p, "w", encoding="utf-8") as f:
    f.write(new_s)
print("PATCH_APPLIED")
PY'
